    internal static bool TryGetCreationRow(NpcTypeId type, out CreationRow row)
    {
        foreach (var source in CreationRows)
            if (source.Type == type.Value) { row = source; return true; }
        row = default; return false;
    }

    public static bool TryGetCreation(NpcTypeId type, NpcNetId netId, out VanillaNpcDefinition definition)
    {
        definition = default;
        if (!TryGetCreationRow(type, out var row)) return false;
        bool variant = type.Value == 183 && netId.Value is -25 or -24;
        if (!variant && (type.Value == 183 || netId.Value != type.Value)) return false;
        if (!TryGet(type, netId, out var source)) return false;
        definition = source with { DefinitionOnly = false, CreationDefaultsOnly = true,
            BaseWidth = row.Width, BaseHeight = row.Height,
            Role = row.Boss ? NpcArchetypeRole.Boss : NpcArchetypeRole.Ordinary,
            SourceNetId = variant ? netId : default };
        if (variant)
        {
            var context = new VanillaNpcSpawnContext(1f, 1, false);
            if (!VanillaNpcSpawnDefaults.TryResolveRemainingSourceRoster(in definition, in context,
                    OperatingSystem.IsWindows(), out var classic)) return false;
            definition = definition with { LifeMax = classic.LifeMax, Damage = classic.Damage, Defense = classic.Defense,
                KnockBackResist = classic.KnockBackResist!.Value, SourceHitboxAtSpawn = classic.Hitbox };
        }
        return true;
    }
